1	/* Fringe Discover — front-end logic
2	 * - loads mock show data (all happening *today*, scoped to the next few hours)
3	 * - renders an interactive Leaflet map of Edinburgh venues
4	 * - renders the "Happening Now" list
5	 * - three interactive constraint filters:
6	 *     1. Genre      — multi-select of Fringe categories (filters map + list)
7	 *     2. Travel     — how you're getting to the next show
8	 *     3. Next show  — pick the exact start time, then the show, and pin it
9	 *
10	 * Loaded as an ES module (`<script type="module">` in index.html) so it can share
11	 * real code with the planner instead of copy-pasting it — see shared/geo.js.
12	 */
13	
14	import { isInUK } from "../shared/geo.js";
15	
16	const EDINBURGH = [55.9486, -3.1881];
17	
18	/* Default "you are here" pin — central Edinburgh (Princes Street / Royal Mile
19	 * area) so the UI has a sensible starting point before / unless the user shares
20	 * their real location. */
21	const USER_DEFAULT = [55.9523946827963, -3.188258484671504];
22	
23	/* Google Maps logo (marks the "Open in Maps" link that opens Google Maps).
24	 * Inline SVG so it needs no network and inherits crisp scaling. */
25	const GMAPS_LOGO =
26	  '<svg class="gmaps-logo" viewBox="0 0 40 40" width="15" height="15" aria-hidden="true" focusable="false">' +
27	  '<defs><clipPath id="gmapsPin"><path d="M20 2C12.8 2 7 7.8 7 15c0 8.6 10.3 19.5 12.2 21.5.4.5 1.2.5 1.6 0C22.7 34.5 33 23.6 33 15 33 7.8 27.2 2 20 2z"/></clipPath></defs>' +
28	  '<g clip-path="url(#gmapsPin)">' +
29	  '<path fill="#4285F4" d="M20 15 L0 40 L0 0 Z"/>' +
30	  '<path fill="#EA4335" d="M20 15 L0 0 L40 0 Z"/>' +
31	  '<path fill="#FBBC04" d="M20 15 L40 0 L40 40 Z"/>' +
32	  '<path fill="#34A853" d="M20 15 L40 40 L0 40 Z"/>' +
33	  '</g><circle cx="20" cy="15" r="4.6" fill="#fff"/></svg>';
34	
35	/* The official-style Fringe genre categories. */
36	const GENRES = [
37	  "Cabaret and Variety",
38	  "Children's Shows",
39	  "Comedy",
40	  "Dance, Physical Theatre & Circus",
41	  "Events",
42	  "Exhibitions",
43	  "Music",
44	  "Musicals and Opera",
45	  "Spoken Word",
46	  "Theatre",
47	];
48	
49	/* How the user might travel between shows, and rough door-to-door speeds
50	 * (km/h) used to estimate travel time. (No bus mode — we can't give honest
51	 * schedules, so it would mislead more than help.) */
52	const TRAVEL_MODES = ["Walking", "Taxi/Car", "Bicycle"];
53	const TRAVEL_SPEEDS_KMH = {
54	  // Walking dialled down to ~2/3 of a brisk 5 km/h — Edinburgh's closes, hills,
55	  // stairs and festival crowds make real walking slower than the crow flies.
56	  Walking: (5 * 2) / 3,
57	  "Taxi/Car": 30,
58	  Bicycle: 15,
59	};
60	
61	/* Reachability window. The user picks how far they'll travel (in minutes) in
62	 * the travel card; DEFAULT_MAX_TRAVEL seeds it. The slider runs 1–60 min in
63	 * one-minute steps. A show that starts up to GRACE_MINUTES before you'd
64	 * actually arrive is still shown, but faded — you'd only just miss it. */
65	const DEFAULT_MAX_TRAVEL = 10;
66	const MIN_TRAVEL_MINUTES = 1;
67	const MAX_TRAVEL_MINUTES = 60;
68	const GRACE_MINUTES = 5;
69	
70	/* Price filter — the source data only distinguishes free vs paid (no amounts),
71	 * so it's a three-way choice: both | free | paid. */
72	const PRICE_FILTERS = ["both", "free", "paid"];
73	
74	/* ===== DEBUG: simulated "now" =====================================
75	 * The whole flow is scoped to "the next few hours today", so for testing we
76	 * pin a fixed clock instead of the real one. A red on-screen badge makes it
77	 * obvious the app is running against a faked time. */
78	const NOW = {
79	  date: "2026-08-14",   // which day's data file to load (data/days/<date>.json)
80	  dateLabel: "Fri 14 Aug",
81	  time: "15:44",
82	  tz: "BST",            // British Summer Time
83	  minutes: 15 * 60 + 44,
84	};
85	
86	/* Backing Date for the simulated clock. The debug date/time picker reads and
87	 * writes this, and we project it onto NOW (which is used throughout the app).
88	 * The year is arbitrary — only the day/time matter to the demo. */
89	let simNowDate = new Date(2026, 7, 14, 15, 44); // Fri 14 Aug 2026, 15:44 (matches the data year)
90	
91	const state = {
92	  shows: [],
93	  venues: {},                  // venue code -> { name, address, postcode, lat, lng }
94	  markers: {},                 // id -> Leaflet marker
95	  clusterGroup: null,          // Leaflet.markercluster group for the non-focused pins
96	  map: null,
97	  selectedGenres: new Set(["Comedy"]),
98	  priceFilter: "both",         // "both" | "free" | "paid" (genre card)
99	  travelMode: "Walking",
100	  maxTravelMinutes: DEFAULT_MAX_TRAVEL, // reach window from the travel card
101	  selectedTime: "",            // chosen exact start time, e.g. "16:30"
102	  selectedShowId: "",          // the pinned "next show" (destination)
103	  destLabel: "",               // editable destination text (defaults to the show's venue)
104	  legShowId: "",               // a show clicked on the map (stop before the destination)
105	  editingCommitment: false,    // constraint panel opened from the plan to change it
106	  spareCtaDismissed: false,    // user hid the in-plan "time to spare" prompt
107	  viewMode: "map",             // the one selector under the filters: "map" | "closest" | "soonest"
108	  view: "map",                 // pane the mode implies: "map" | "list" (map is default)
109	  sortBy: "time",              // reachable-list order the mode implies: "time" | "distance"
110	  userLatLng: USER_DEFAULT,    // current "you are here" location
111	  userMarker: null,            // Leaflet marker for the user
112	  reachCircle: null,           // Leaflet circle for the travel radius
113	  routeLayers: [],             // Leaflet layers for the journey arrows/labels
114	};
115	
116	/* ---------- Boot ---------- */
117	document.addEventListener("DOMContentLoaded", init);
118	
119	async function init() {
120	  renderDebugBanner();
121	  wireDebugControls();
122	  initMap();
123	  setUserLocation(USER_DEFAULT, { recenter: false }); // central-Edinburgh default
124	  requestUserLocation();                              // then ask for the real thing
125	  buildGenrePanel();
126	  buildTravelPanel();
127	  wirePanels();
128	  wireViewSwitch();
129	  // The header pin re-asks the browser for the user's location (same as the
130	  // map's ◎ control) and recentres on it.
131	  const locBtn = document.getElementById("locBtn");
132	  if (locBtn) locBtn.addEventListener("click", requestUserLocation);
133	  await loadShows();
134	  buildConstraintPanel();
135	  refreshMap();
136	  renderShowList();
137	  updateGenreValue();
138	}
139	
140	/* ---------- Data loading ---------- */
141	/* Load today's shows: the per-day file (only today's performances, kept small)
142	 * joined with the venue lookup (names + coordinates), reshaped for the map and
143	 * list. Only the current day is fetched, so the payload stays light. */
144	async function loadShows() {
145	  try {
146	    const [venuesRes, dayRes] = await Promise.all([
147	      fetch("data/venues.json"),
148	      fetch(`data/days/${NOW.date}.json`),
149	    ]);
150	    if (!venuesRes.ok) throw new Error(`venues HTTP ${venuesRes.status}`);
151	    if (!dayRes.ok) throw new Error(`day ${NOW.date} HTTP ${dayRes.status}`);
152	    // The shared lookup file carries the venue map plus the global rooms/genres
153	    // lists that the day records index into. Fetched once.
154	    const lookups = await venuesRes.json();
155	    state.venues = lookups.venues;
156	    state.rooms = lookups.rooms || [];
157	    state.genres = lookups.genres || [];
158	    state.subgenres = lookups.subgenres || [];
159	    state.ticketStatuses = lookups.ticketStatuses || [];
160	    const day = await dayRes.json();
161	    // Drop shows whose venue we couldn't geocode — they can't be placed on the map.
162	    state.shows = day
163	      .map((entry, i) => adaptShow(entry, state, i))
164	      .filter((s) => s.lat != null && s.lng != null);
165	  } catch (err) {
166	    console.error("Could not load show data:", err);
167	    state.shows = [];
168	  }
169	}
170	
171	/* Join a minimal per-day record with its venue and expand to the model the map
172	 * and list expect ({ id, title, genre, venue, lat, lng, time, duration, price }).
173	 * The day record references genre, room, subgenres and ticket status by index
174	 * into the global `state.genres`/`state.rooms`/`state.subgenres`/
175	 * `state.ticketStatuses` lookup lists (room index -1, or an unknown room,
176	 * resolves to no room), and stores free/soldOut as 1/0. A show can perform more
177	 * than once a day, so the internal id is made unique per performance. */
178	function adaptShow(entry, { venues, rooms, genres, subgenres, ticketStatuses }, index) {
179	  const v = venues[entry.venue] || {};
180	  const venueName = v.name || (entry.venue ? `Venue ${entry.venue}` : "Venue TBC");
181	  const room = rooms[entry.room];
182	  const ticketStatus = (ticketStatuses || [])[entry.ts] || null;
183	  return {
184	    id: `${entry.id}__${entry.start}__${index}`,
185	    showId: entry.id,
186	    slug: entry.slug,
187	    title: entry.title,
188	    genre: genres[entry.genre],
189	    subgenres: (entry.subs || []).map((i) => (subgenres || [])[i]).filter(Boolean),
190	    venue: room ? `${venueName} — ${room}` : venueName,
191	    lat: v.lat ?? null,
192	    lng: v.lng ?? null,
193	    time: entry.start,
194	    duration: entry.duration || 60,
195	    free: !!entry.free,
196	    price: entry.free ? "Free" : "Paid",
197	    soldOut: !!entry.soldOut,
198	    ticketStatus,
199	    // Can you actually get a ticket online? ticketStatus is the reliable signal
200	    // (the soldOut flag isn't — see scraper/SCRAPING.md). Unknown ⇒ assume yes.
201	    available: !NO_TICKETS_STATUSES.has(ticketStatus),
202	  };
203	}
204	
205	/* Ticket statuses that mean "no ticket available online" → SOLD OUT stamp.
206	 * Anything else (incl. unknown) is treated as available. */
207	const NO_TICKETS_STATUSES = new Set(["SOLD_OUT", "NO_ALLOCATION_CONTACT_VENUE"]);
208	
209	/* ---------- Map ---------- */
210	function initMap() {
211	  const map = L.map("leaflet-map", { scrollWheelZoom: false }).setView(EDINBURGH, 14);
212	  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
213	    maxZoom: 19,
214	    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
215	  }).addTo(map);
216	
217	
218	  state.map = map;
219	}
220	
221	/* ---------- User location ---------- */
222	function userIcon() {
223	  return L.divIcon({
224	    className: "user-marker",
225	    html: '<span class="user-dot"></span>',
226	    iconSize: [20, 20],
227	    iconAnchor: [10, 10],
228	  });
229	}
230	
231	/* Drop or move the "you are here" marker. opts.recenter pans the map to it. */
232	function setUserLocation(latlng, { recenter = true, real = false } = {}) {
233	  state.userLatLng = latlng;
234	  const label = real ? "You are here" : "You are here (approx. central Edinburgh)";
235	
236	  if (state.userMarker) {
237	    state.userMarker.setLatLng(latlng);
238	  } else {
239	    state.userMarker = L.marker(latlng, {
240	      icon: userIcon(),
241	      zIndexOffset: 1000,
242	      keyboard: false,
243	    }).addTo(state.map);
244	  }
245	  state.userMarker.bindPopup(`<p class="popup-title">${label}</p>`);
246	
247	  if (recenter && state.map) state.map.setView(latlng, 15, { animate: true });
248	  if (state.shows.length) refreshMap(); // reachable set depends on where we are
249	}
250	
251	/* Ask the browser for the user's real location and move the pin there. */
252	function requestUserLocation() {
253	  if (!("geolocation" in navigator)) {
254	    console.warn("Geolocation not supported; keeping default location.");
255	    return;
256	  }
257	  navigator.geolocation.getCurrentPosition(
258	    (pos) => {
259	      const here = [pos.coords.latitude, pos.coords.longitude];
260	      // Testing guard: outside the UK (e.g. an overseas tester) keep the
261	      // central-Edinburgh default and show the pre-set values instead.
262	      if (!isInUK(here)) {
263	        console.info(
264	          `Real location (${here[0].toFixed(3)}, ${here[1].toFixed(3)}) is outside the UK — ` +
265	            "keeping the central Edinburgh default for testing."
266	        );
267	        return;
268	      }
269	      // In the UK we trust the real location, so the pre-set values (and the
270	      // debug tools that tweak them) are no longer relevant — hide them.
271	      setUserLocation(here, { recenter: true, real: true });
272	      setDebugVisible(false);
273	    },
274	    (err) => {
275	      // Denied / unavailable / timed out — keep the central-Edinburgh default.
276	      console.info("Using default location:", err && err.message);
277	    },
278	    { enableHighAccuracy: true, timeout: 8000, maximumAge: 60000 }
279	  );
280	}
281	
282	function genreColor(genre) {
283	  const map = {
284	    Comedy: "#c62024",
285	    Theatre: "#9c181b",
286	    "Dance, Physical Theatre & Circus": "#c79a36",
287	    Music: "#2f6bd6",
288	    "Cabaret and Variety": "#8e44ad",
289	    "Musicals and Opera": "#16a085",
290	    "Spoken Word": "#34495e",
291	    "Children's Shows": "#27ae60",
292	    Events: "#e67e22",
293	    Exhibitions: "#2c3e50",
294	  };
295	  return map[genre] || "#141414";
296	}
297	
298	/* Price bucket for filtering: free -> 0, paid -> 1. The source data has no
299	 * ticket amounts, so paid shows are only distinguished from free ones. */
300	function priceValue(show) {
301	  return show.free || /free/i.test(show.price) ? 0 : 1;
302	}
303	
304	/* Shows passing the current genre + price filters (empty genre set = all). */
305	function visibleShows() {
306	  let list = state.shows;
307	  if (state.selectedGenres.size) {
308	    list = list.filter((s) => state.selectedGenres.has(s.genre));
309	  }
310	  if (state.priceFilter === "free") list = list.filter((s) => priceValue(s) === 0);
311	  else if (state.priceFilter === "paid") list = list.filter((s) => priceValue(s) === 1);
312	  return list;
313	}
314	
315	/* How far ahead a "next commitment" must start to be worth picking. There's no
316	 * point letting the user constrain their search to something starting in the
317	 * next few minutes — they couldn't act on it — so we only offer start times at
318	 * least CONSTRAINT_LEAD_MINUTES from now. */
319	const CONSTRAINT_LEAD_MINUTES = 40;
320	
321	/* Candidate shows for the "next commitment" constraint. This is whatever the
322	 * user already has lined up, NOT part of the current genre/price search, so it
323	 * deliberately ignores the genre + price filter. Only start times at least
324	 * CONSTRAINT_LEAD_MINUTES from now are offered. */
325	function constraintShows() {
326	  return state.shows.filter(
327	    (s) => timeToMinutes(s.time) >= NOW.minutes + CONSTRAINT_LEAD_MINUTES
328	  );
329	}
330	
331	/* Minutes of travel, by the selected mode, from A to B ([lat,lng] each). */
332	function travelMinutes(a, b) {
333	  const speed = TRAVEL_SPEEDS_KMH[state.travelMode] || TRAVEL_SPEEDS_KMH.Walking;
334	  return (distanceKm(a, b) / speed) * 60;
335	}
336	
337	/* Metres covered in the chosen max-travel window at the selected travel speed. */
338	function reachRadiusMeters() {
339	  const speed = TRAVEL_SPEEDS_KMH[state.travelMode] || TRAVEL_SPEEDS_KMH.Walking;
340	  return speed * (state.maxTravelMinutes / 60) * 1000;
341	}
342	
343	/* Classify a show for the map relative to the user and (optionally) the chosen
344	 * "next show" constraint. Returns "selected" | "ok" | "tight" | "hidden".
345	 *   - ok     : you can travel there and arrive before it starts
346	 *   - tight  : you'd arrive up to GRACE_MINUTES after it starts (faded)
347	 *   - hidden : out of reach, already missed, or won't leave time for your
348	 *              next show
349	 */
350	function classifyShow(show, constraint) {
351	  if (constraint && show.id === constraint.id) return "selected";
352	
353	  const here = state.userLatLng;
354	  const there = [show.lat, show.lng];
355	  const travel = travelMinutes(here, there);
356	  if (travel > state.maxTravelMinutes) return "hidden"; // beyond chosen travel window
357	
358	  const arrival = NOW.minutes + travel;
359	  const start = timeToMinutes(show.time);
360	  const reachInTime = arrival <= start;
361	  const tight = !reachInTime && arrival - start <= GRACE_MINUTES;
362	
363	  // With a next show chosen, also require leaving in time to make it.
364	  if (constraint) {
365	    const end = start + show.duration;
366	    const onward = travelMinutes(there, [constraint.lat, constraint.lng]);
367	    const makesConstraint = end + onward <= timeToMinutes(constraint.time);
368	    if (!makesConstraint) return "hidden";
369	    // Once committed to a plan, only keep shows you can comfortably reach.
370	    return reachInTime ? "ok" : "hidden";
371	  }
372	
373	  if (reachInTime) return "ok";
374	  if (tight) return "tight";
375	  return "hidden";
376	}
