378	/* The shows to draw on the map, each with its status. */
379	function displayedShows() {
380	  const constraint = state.selectedShowId
381	    ? state.shows.find((s) => s.id === state.selectedShowId)
382	    : null;
383	
384	  const out = [];
385	  visibleShows().forEach((show) => {
386	    const status = classifyShow(show, constraint);
387	    if (status !== "hidden") out.push({ show, status });
388	  });
389	  // Always keep the chosen next show pinned, even if it's beyond the circle.
390	  if (constraint && !out.some((o) => o.show.id === constraint.id)) {
391	    out.push({ show: constraint, status: "selected" });
392	  }
393	  // Keep the user's selected show pinned too — it stays selected until they
394	  // change it, even if the current commitment/window would otherwise hide it.
395	  if (
396	    state.legShowId &&
397	    state.legShowId !== state.selectedShowId &&
398	    !out.some((o) => o.show.id === state.legShowId)
399	  ) {
400	    const sel = state.shows.find((s) => s.id === state.legShowId);
401	    if (sel) out.push({ show: sel, status: "leg" });
402	  }
403	  // Highlight the show the user selected — a stop before the destination when a
404	  // plan exists, or just the highlighted pin otherwise.
405	  if (state.legShowId) {
406	    const focus = out.find((o) => o.show.id === state.legShowId && o.status !== "selected");
407	    if (focus) focus.status = "leg";
408	  }
409	  // Draw highlighted pins last so they sit on top.
410	  const z = { ok: 0, tight: 0, leg: 1, selected: 2 };
411	  out.sort((a, b) => (z[a.status] || 0) - (z[b.status] || 0));
412	  return out;
413	}
