432	/* A map pin as the genre emoji inside a subtle transparent ring — a thin,
433	 * semi-transparent white border defines the marker without the heavy white disc
434	 * crowding the map. Every pin is the same size; the focused show and committed
435	 * destination are highlighted by a violet ring (see .gpin--selected/--leg), not
436	 * by growing, so they never disturb the map's density. */
437	function genrePin(show, status) {
438	  const size = 22;
439	  const font = Math.round(size * 0.74);
440	  const html = `<span class="gpin gpin--${status}" style="width:${size}px;height:${size}px;font-size:${font}px">${genreIcon(show.genre)}</span>`;
441	  return L.divIcon({
442	    html,
