450	/* Cluster bubble for Leaflet.markercluster — a violet count disc in the page's
451	 * palette, sized up a touch for busier clusters. */
452	function clusterIcon(cluster) {
453	  const n = cluster.getChildCount();
454	  const size = n < 10 ? 30 : n < 50 ? 36 : 42;
455	  // When a show is focused, the individual pins step back — so the count bubbles
456	  // must fade too, or they'd sit there loud and opaque while everything else dims.
457	  const dim = state.legShowId ? " gcluster--dim" : "";
458	  return L.divIcon({
459	    html: `<span class="gcluster${dim}" style="width:${size}px;height:${size}px">${n}</span>`,
460	    className: "genre-cluster",
461	    iconSize: [size, size],
462	    iconAnchor: [size / 2, size / 2],
463	  });
464	}
