512	function renderReachCircle() {
513	  if (!state.map) return;
514	  const opts = {
515	    radius: reachRadiusMeters(),
516	    color: "#6c4cf1",
517	    weight: 1.5,
518	    fillColor: "#6c4cf1",
519	    fillOpacity: 0.08,
520	    interactive: false,
521	  };
522	  if (state.reachCircle) {
523	    state.reachCircle.setLatLng(state.userLatLng).setRadius(opts.radius);
524	  } else {
525	    state.reachCircle = L.circle(state.userLatLng, opts).addTo(state.map);
526	  }
527	  state.reachCircle.bindTooltip(
528	    `~${state.maxTravelMinutes} min by ${state.travelMode}`,
529	    { permanent: false, direction: "top" }
530	  );
531	}
