533	function renderMarkers() {
534	  if (!state.map) return;
535	
536	  // Cluster group for the ordinary pins — collapses dense / overlapping shows
537	  // into a count bubble that splits (and spiderfies coincident pins) on zoom.
538	  // Guarded: if the plugin CDN failed to load, we degrade to plain markers so
539	  // the map still works rather than throwing.
540	  if (!state.clusterGroup && typeof L.markerClusterGroup === "function") {
541	    state.clusterGroup = L.markerClusterGroup({
542	      maxClusterRadius: 26,      // px; smaller = only genuinely close pins merge
543	      spiderfyOnMaxZoom: true,   // fan out pins sharing a spot when fully zoomed
544	      showCoverageOnHover: false,
545	      iconCreateFunction: clusterIcon,
546	    });
547	    state.map.addLayer(state.clusterGroup);
548	  }
549	
550	  // Clear the previous render: clustered pins live in the group, the focused /
551	  // destination pins are added straight to the map, so clear both.
552	  if (state.clusterGroup) state.clusterGroup.clearLayers();
553	  Object.values(state.markers).forEach((m) => {
554	    if (state.map.hasLayer(m)) state.map.removeLayer(m);
555	  });
556	  state.markers = {};
557	
558	  // Only when the user has actually tapped a show to focus it do the other pins
559	  // step back — a committed next commitment on its own shouldn't grey out the
560	  // options you're browsing to fill the gap.
561	  const anyFocus = Boolean(state.legShowId);
562	  displayedShows().forEach(({ show, status }) => {
563	    const prominent = status === "selected" || status === "leg";
564	    const dim = anyFocus && !prominent;
565	    const marker = L.marker([show.lat, show.lng], {
566	      icon: genrePin(show, status),
567	      zIndexOffset: status === "selected" ? 1000 : status === "leg" ? 600 : 0,
568	      keyboard: false,
569	    });
570	    marker.setOpacity(dim ? 0.25 : status === "tight" ? 0.55 : 1);
571	
572	    if (prominent) {
573	      // Keep the highlighted pins out of clusters so they're always visible.
574	      // (No name tooltip — the focus card / plan carries the title; a permanent
575	      // label here just added noise. The ✓-arrival time sits above instead.)
576	      marker.addTo(state.map);
577	    } else if (state.clusterGroup) {
578	      state.clusterGroup.addLayer(marker);
579	    } else {
580	      marker.addTo(state.map); // plugin unavailable — plain marker fallback
581	    }
582	
583	    // Tapping a pin selects the show (updates the map + draws its path) but,
584	    // unlike the list, does NOT scroll the page — map browsing stays put.
585	    marker.on("click", () => onShowClick(show));
586	    state.markers[show.id] = marker;
587	  });
588	}
