590	/* Select a show (from the list or a map pin): it becomes the stop on the way to
591	 * any commitment, draws its path, and the other pins dim. Selecting it again
592	 * clears it. The list additionally scrolls up to the plan; the map does not. The
593	 * committed destination itself isn't a re-selectable focus. */
594	function onShowClick(show) {
595	  if (show.id === state.selectedShowId) return; // already the committed destination
596	  state.legShowId = state.legShowId === show.id ? "" : show.id; // toggle selection
597	  refreshMap();
598	}
