600	/* ---------- Journey arrows ---------- */
601	function renderRoute() {
602	  if (!state.map) return;
603	  // Clear previous arrows/labels.
604	  state.routeLayers.forEach((l) => state.map.removeLayer(l));
605	  state.routeLayers = [];
606	
607	  const dest = state.selectedShowId
608	    ? state.shows.find((s) => s.id === state.selectedShowId)
609	    : null;
610	
611	  // No commitment yet, but a show is selected: still draw the walk to it, with
612	  // the same travel pill and the ✓ "you make its start" check.
613	  if (!dest) {
614	    const sel = state.legShowId ? state.shows.find((s) => s.id === state.legShowId) : null;
615	    if (sel) {
616	      drawLeg(state.userLatLng, [sel.lat, sel.lng], { checkMin: timeToMinutes(sel.time) });
617	    }
618	    return;
619	  }
620	  const destPt = [dest.lat, dest.lng];
621	
622	  // Is there a valid intermediate stop the user clicked?
623	  let leg = null;
624	  if (state.legShowId && state.legShowId !== dest.id) {
625	    const cand = state.shows.find((s) => s.id === state.legShowId);
626	    if (cand && classifyShow(cand, dest) === "ok") leg = cand;
627	  }
628	
629	  if (leg) {
630	    const legPt = [leg.lat, leg.lng];
631	    // Leg 1: leave now, arrive before this show starts.
632	    drawLeg(state.userLatLng, legPt, {
633	      checkMin: timeToMinutes(leg.time), // show start (your arrival is before this)
634	    });
635	    // Leg 2: leave when this show ends, arrive before your next commitment.
636	    drawLeg(legPt, destPt, {
637	      checkMin: timeToMinutes(dest.time), // constraint start
638	    });
639	  } else {
640	    // Single leg: leave now, arrive before your next commitment.
641	    drawLeg(state.userLatLng, destPt, { checkMin: timeToMinutes(dest.time) });
642	  }
643	}
644	
645	/* Draw one animated arrow leg. The green check above the destination pin shows
646	 * the deadline that arrival comfortably beats (a show start, or your next
647	 * commitment). The leg's clock window lives in the itinerary, not on the map. */
648	function drawLeg(from, to, { checkMin } = {}) {
649	  const line = L.polyline([from, to], {
650	    className: "route-line",
651	    color: "#141414",
652	    weight: 3,
653	    opacity: 0.9,
654	    interactive: false,
655	  }).addTo(state.map);
656	  state.routeLayers.push(line);
657	
658	  // Arrowhead near the destination end, rotated to the bearing.
659	  const head = L.marker(lerp(from, to, 0.82), {
660	    icon: L.divIcon({
661	      className: "route-arrow-wrap",
662	      html: `<span class="route-arrow" style="transform:rotate(${bearing(from, to)}deg)"></span>`,
663	      iconSize: [16, 16],
664	      iconAnchor: [8, 8],
665	    }),
666	    interactive: false,
667	    keyboard: false,
668	  }).addTo(state.map);
669	  state.routeLayers.push(head);
670	
671	  // Green check with the deadline you're beating, sitting directly above the
672	  // destination pin. The marker root is a zero-size anchor pinned exactly on the
673	  // point; the visible pill is an inner span, so its centring transform survives
674	  // (Leaflet writes its own inline transform on the root to place it, which would
675	  // otherwise clobber a transform set on the root itself).
676	  if (checkMin != null) {
677	    const chk = L.marker(to, {
678	      icon: L.divIcon({
679	        className: "route-check-marker",
680	        html: `<span class="route-label route-check"><span class="tick">✓</span> ${minutesToTime(checkMin)}</span>`,
681	        iconSize: [0, 0],
682	        iconAnchor: [0, 0],
683	      }),
684	      interactive: false,
685	      keyboard: false,
686	      zIndexOffset: 1100,
687	    }).addTo(state.map);
688	    state.routeLayers.push(chk);
689	  }
690	}
