696	/* The verb for a leg, matching the selected travel mode: "5 min walk" /
697	 * "5 min by taxi" / "5 min by bike". Keeps the itinerary honest when the mode
698	 * switches away from walking. */
699	function travelVerb() {
700	  return { Walking: "walk", "Taxi/Car": "by taxi", Bicycle: "by bike" }[state.travelMode] || "walk";
