703	/* ---------- Show list ---------- */
704	/* The list mirrors what's on the map, minus the chosen next commitment: that
705	 * show is a future destination the user has already locked in, not something
706	 * "Happening Now", so we pin it on the map but keep it out of this list. */
707	/* How many list rows to show before the "Show more" button; grows on demand. */
708	const SHOW_PAGE = 12;
709	
710	/* The reachable shows to list (excluding the chosen next show). Without a
711	 * commitment, "on now" means the next couple of hours — not the whole day — so
712	 * the list stays about spontaneity, not a full catalogue. Order-independent:
713	 * the caller sorts by time or distance. */
714	function fittingShows() {
715	  const constrained = Boolean(state.selectedShowId);
716	  const constraint = constrained
717	    ? state.shows.find((s) => s.id === state.selectedShowId)
718	    : null;
719	  let all = displayedShows().filter(({ show }) => show.id !== state.selectedShowId);
720	  // A selected show that can't actually be slipped in before the commitment isn't
721	  // a real option — keep it on the map and the itinerary, but out of this list
722	  // and its count (so "N shows you can slip in" stays honest).
723	  if (constraint && state.legShowId) {
724	    const leg = state.shows.find((s) => s.id === state.legShowId);
725	    if (leg && classifyShow(leg, constraint) !== "ok") {
726	      all = all.filter(({ show }) => show.id !== state.legShowId);
727	    }
728	  }
729	  if (!constrained) {
730	    all = all.filter(({ show }) => timeToMinutes(show.time) <= NOW.minutes + 120);
731	  }
732	  return all;
733	}
734	
735	function renderShowList() {
736	  const grid = document.getElementById("showsGrid");
737	  const title = document.querySelector(".shows-title");
738	  const moreBtn = document.getElementById("showMore");
739	  if (!grid) return;
740	  grid.innerHTML = "";
741	
742	  const constraint = state.selectedShowId
743	    ? state.shows.find((s) => s.id === state.selectedShowId)
744	    : null;
745	
746	  const all = fittingShows();
747	  // Walk minutes: computed once, reused for the row label and distance sort.
748	  all.forEach((o) => {
749	    o.walk = Math.max(1, Math.round(travelMinutes(state.userLatLng, [o.show.lat, o.show.lng])));
750	  });
751	  const byDistance = state.sortBy === "distance";
752	  if (byDistance) all.sort((a, b) => a.walk - b.walk || a.show.time.localeCompare(b.show.time));
753	  else all.sort((a, b) => a.show.time.localeCompare(b.show.time));
754	
755	  if (title) {
756	    const n = all.length;
757	    const shows = n === 1 ? "show" : "shows";
758	    title.textContent = constraint
759	      ? `${n} ${shows} you can slip in before ${constraint.time}`
760	      : `${n} ${shows} you could wander into right now`;
761	  }
762	
763	  if (!all.length) {
764	    grid.innerHTML =
765	      '<p class="show-meta">' +
766	      (constraint
767	        ? "Nothing fits before your next commitment — try a later time or a wider travel window."
768	        : "Nothing reachable in the next couple of hours — widen your travel window or taste.") +
769	      "</p>";
770	    if (moreBtn) moreBtn.hidden = true;
771	    return;
772	  }
773	
774	  const cap = state.showCap || SHOW_PAGE;
775	  const shown = all.slice(0, cap);
776	
777	  // Compact rows. Sorting by time groups under start-time headings; sorting by
778	  // distance is a flat nearest-first list (each row still shows its time).
779	  let group = null;
780	  shown.forEach(({ show, status, walk }) => {
781	    if (!byDistance && show.time !== group) {
782	      group = show.time;
783	      const head = document.createElement("h3");
784	      head.className = "shows-group-head";
785	      head.textContent = show.time;
786	      grid.appendChild(head);
787	    }
788	    const item = document.createElement("article");
789	    item.className = `show-item show-item--${status}${show.available ? "" : " show-item--soldout"}`;
790	    item.tabIndex = 0;
791	    item.setAttribute("role", "button");
792	    item.innerHTML = `
793	      ${showStamp(show, status)}
794	      <span class="si-main">
795	        <span class="show-genre">${escapeHtml(show.genre)}</span>
796	        <span class="show-name">${escapeHtml(show.title)}</span>
797	        <span class="show-meta">${escapeHtml(show.venue)}</span>
798	        ${subgenreTags(show)}
799	      </span>
800	      <span class="si-side">
801	        <span class="si-time">${escapeHtml(show.time)}</span><br />
802	        <span class="si-walk">🚶 ${walk} min · ${escapeHtml(show.price)}</span>
803	        ${constraint ? '<br /><span class="si-fits">fits</span>' : ""}
804	      </span>`;
805	    const activate = () => {
806	      onShowClick(show);
807	      // Selecting from the list promotes the show into the plan at the top of the
808	      // page — scroll all the way up so the whole itinerary reads top-to-bottom
809	      // (scrolling only to the plan tucked its header under the sticky nav).
810	      if (state.legShowId === show.id) {
811	        window.scrollTo({ top: 0, behavior: "smooth" });
812	      }
813	    };
814	    item.addEventListener("click", activate);
815	    item.addEventListener("keydown", (e) => {
816	      if (e.key === "Enter" || e.key === " ") {
817	        e.preventDefault();
818	        activate();
819	      }
820	    });
821	    grid.appendChild(item);
822	  });
823	
824	  if (moreBtn) {
825	    const remaining = all.length - shown.length;
826	    moreBtn.hidden = remaining <= 0;
827	    moreBtn.textContent = `Show ${Math.min(SHOW_PAGE, remaining)} more · ${remaining} left`;
828	  }
829	}
