831	/* ---------- View selector: Map | Closest | Soonest ---------- */
832	/* One control carries both decisions. The map and the reachable list are two
833	 * views of the same shows, and the list only ever has two useful orders — so
834	 * rather than a view toggle plus a sort toggle, the three positions here are
835	 * the three things you can actually be looking at. Map is the default. The
836	 * filters above act on all three, so nothing here touches them. */
837	const VIEW_MODES = {
838	  map: { view: "map" },
839	  closest: { view: "list", sortBy: "distance" },
840	  soonest: { view: "list", sortBy: "time" },
841	};
842	
843	function applyViewMode(mode) {
844	  const spec = VIEW_MODES[mode] || VIEW_MODES.map;
845	  const orderChanged = spec.sortBy && spec.sortBy !== state.sortBy;
846	  state.viewMode = mode;
847	  state.view = spec.view;
848	  if (spec.sortBy) state.sortBy = spec.sortBy;
849	
850	  const mapPane = document.getElementById("map");
851	  const listPane = document.getElementById("shows");
852	  if (mapPane) mapPane.hidden = state.view !== "map";
853	  if (listPane) listPane.hidden = state.view !== "list";
854	
855	  const area = document.querySelector(".view-area");
856	  if (area) area.dataset.view = state.view;
857	
858	  updateViewButtons();
859	
860	  // A new order starts from the first page, so the top of the list is the part
861	  // that actually answers "closest" / "soonest".
862	  if (orderChanged) {
863	    state.showCap = SHOW_PAGE;
864	    renderShowList();
865	  }
866	
867	  // Leaflet can't measure a display:none container, so a map hidden while the
868	  // list showed comes back mis-sized — re-measure once it's visible again.
869	  if (state.view === "map" && state.map) state.map.invalidateSize();
870	}
871	
872	/* Reflect the active mode on the three-position selector. */
873	function updateViewButtons() {
874	  document.querySelectorAll(".view-btn[data-mode]").forEach((b) => {
875	    const on = b.dataset.mode === state.viewMode;
876	    b.classList.toggle("is-active", on);
877	    b.setAttribute("aria-pressed", String(on));
878	  });
879	}
880	
881	/* Wire the selector. All three positions stay visible, so any of them is one
882	 * click away from any other. */
883	function wireViewSwitch() {
884	  document.querySelectorAll(".view-btn[data-mode]").forEach((btn) => {
885	    btn.addEventListener("click", () => {
886	      if (state.viewMode === btn.dataset.mode) return;
887	      applyViewMode(btn.dataset.mode);
888	    });
889	  });
890	  applyViewMode(state.viewMode); // establish the default (map)
891	}
892	
893	/* ---------- Journey strip ---------- */
894	/* A narrow, always-visible timeline between the filters and the map. It mirrors
895	 * the journey the map is drawing, left → right:
896	 *   • origin  — "You are here", now (always shown, styled dull)
897	 *   • middle  — nothing chosen yet: an animated walker idling in place;
898	 *               a destination chosen: the leg(s) to it with travel time + slack
899	 *   • right   — your next commitment, once chosen
900	 * The slack chip notes how long you'd have before each show starts. */
901	function renderJourneyStrip() {
902	  const strip = document.getElementById("journeyStrip");
903	  if (!strip) return;
904	
905	  const origin = state.userLatLng;
906	  const constraint = state.selectedShowId
907	    ? state.shows.find((s) => s.id === state.selectedShowId)
908	    : null;
909	  // The selected show to slip in — kept independent of the commitment. It shows
910	  // in the plan whenever one is selected (and it isn't the commitment itself),
911	  // even if it no longer neatly fits: the slack chip tells that story.
912	  const leg =
913	    state.legShowId && (!constraint || state.legShowId !== constraint.id)
914	      ? state.shows.find((s) => s.id === state.legShowId)
915	      : null;
916	
917	  // Nothing chosen at all — no plan to show; the list heading carries the state.
918	  if (!constraint && !leg) {
919	    strip.innerHTML = "";
920	    return;
921	  }
922	
923	  // The plan header carries a mild "open in Maps" link on its right (only useful
924	  // once there's a commitment to route toward) — a quiet offer, not a big button.
925	  const parts = [
926	    '<div class="plan-head-row">' +
927	      '<p class="plan-head">Your plan</p>' +
928	      (constraint
929	        ? '<a id="mapsRouteLink" class="plan-maps-mild" href="#" target="_blank" rel="noopener" ' +
930	          'title="Open this route in Google Maps">' + GMAPS_LOGO + " Open in Maps</a>"
931	        : "") +
932	    "</div>",
933	  ];
934	  parts.push(planNode("📍", "you", `${NOW.time} · now`, "You are here", state.travelMode.toLowerCase(), "", ""));
935	
936	  if (leg) {
937	    const legPt = [leg.lat, leg.lng];
938	    const arriveLeg = NOW.minutes + travelMinutes(origin, legPt);
939	    // Can you slip this show in and still make the commitment? If not, the show —
940	    // not the commitment — is where the problem belongs.
941	    const legFits = !constraint || classifyShow(leg, constraint) === "ok";
942	
943	    parts.push(planLeg(travelMinutes(origin, legPt)));
944	    parts.push(
945	      planNode(
946	        genreIcon(leg.genre),
947	        "stop",
948	        `${leg.time}–${minutesToTime(timeToMinutes(leg.time) + leg.duration)}`,
949	        leg.title,
950	        `${leg.venue} · ${leg.genre}`,
951	        legFits
952	          ? planSlack(timeToMinutes(leg.time) - arriveLeg)
953	          : '<span class="plan-slack wontfit">You\'ll be late</span>',
954	        `${subgenreTags(leg)}${planBuy(leg)}`
955	      )
956	    );
957	    if (constraint) {
958	      const destPt = [constraint.lat, constraint.lng];
959	      if (legFits) {
960	        // Sequential detour: leave when the show ends, then on to the commitment.
961	        const departFromLeg = timeToMinutes(leg.time) + leg.duration;
962	        const arriveDest = departFromLeg + travelMinutes(legPt, destPt);
963	        parts.push(planLeg(travelMinutes(legPt, destPt)));
964	        parts.push(
965	          planNode(genreIcon(constraint.genre), "dest", constraint.time, destinationLabel(), "Your next commitment",
966	            planSlack(timeToMinutes(constraint.time) - arriveDest), "")
967	        );
968	      } else {
969	        // The show breaks this plan — present the commitment as reachable directly
970	        // (skip the show), with no alarming pill of its own: it isn't the problem.
971	        const arriveDest = NOW.minutes + travelMinutes(origin, destPt);
972	        parts.push(planLeg(travelMinutes(origin, destPt)));
973	        parts.push(
974	          planNode(genreIcon(constraint.genre), "dest", constraint.time, destinationLabel(), "Your next commitment",
975	            planSlack(timeToMinutes(constraint.time) - arriveDest), "")
976	        );
977	      }
978	    }
979	  } else {
980	    const destPt = [constraint.lat, constraint.lng];
981	    const arriveDest = NOW.minutes + travelMinutes(origin, destPt);
982	    // Middle slot: until a show is slipped in, offer the plan's spare time as a
983	    // prompt where the chosen show will go. It's dismissable, and gets replaced
984	    // by the show's own node once one is picked (the `leg` branch above). When
985	    // there's nothing to offer it falls back to a plain walk connector.
986	    const spareNode = spareCtaNode();
987	    parts.push(spareNode || planLeg(travelMinutes(origin, destPt)));
988	    parts.push(
989	      planNode(genreIcon(constraint.genre), "dest", constraint.time, destinationLabel(), "Your next commitment",
990	        planSlack(timeToMinutes(constraint.time) - arriveDest), "")
991	    );
992	  }
993	
994	  strip.innerHTML = parts.join("");
995	
996	  // Small, explicit controls (top-right, on the hour line) instead of a whole-
997	  // node mystery click. Same design on both the selected show and the commitment.
998	  wireNodeControls(strip.querySelector(".plan-node.stop"), {
999	    change: () =>
1000	      document.getElementById("shows")?.scrollIntoView({ behavior: "smooth", block: "start" }),
1001	    remove: () => { state.legShowId = ""; refreshMap(); },
1002	    changeLabel: "Pick a different show",
1003	    removeLabel: "Remove selected show",
1004	  });
1005	  wireNodeControls(strip.querySelector(".plan-node.dest"), {
1006	    change: openConstraintEditor,
1007	    remove: clearCommitment,
1008	    changeLabel: "Change your next commitment",
1009	    removeLabel: "Remove your next commitment",
1010	  });
1011	
1012	  updateMapsRouteLink();
1013	  wireSpareCta(strip);
1014	}
1015	
1016	/* Attach the shared "Change ▾ / ×" controls to a plan node (top-right, on the
1017	 * hour line). Both callbacks stop propagation so the doc click-outside handler
1018	 * doesn't interfere. */
1019	function wireNodeControls(node, { change, remove, changeLabel, removeLabel }) {
1020	  if (!node) return;
1021	  node.classList.add("has-node-controls");
1022	  const controls = document.createElement("div");
1023	  controls.className = "node-controls";
1024	  controls.innerHTML =
1025	    `<button type="button" class="chg-link" data-act="change" aria-label="${changeLabel}">Change ▾</button>` +
1026	    `<button type="button" class="chg-x" data-act="remove" aria-label="${removeLabel}">&times;</button>`;
1027	  node.appendChild(controls);
1028	  controls.querySelector('[data-act="change"]').addEventListener("click", (e) => {
1029	    e.stopPropagation();
1030	    change();
1031	  });
1032	  controls.querySelector('[data-act="remove"]').addEventListener("click", (e) => {
1033	    e.stopPropagation();
1034	    remove();
1035	  });
1036	}
1037	
1038	/* Google Maps travel mode matching the user's currently selected one. */
1039	function googleMapsTravelMode() {
1040	  return (
1041	    { Walking: "walking", "Taxi/Car": "driving", Bicycle: "bicycling" }[state.travelMode] ||
1042	    "walking"
1043	  );
1044	}
1045	
1046	/* Build the Google Maps URL for the current plan. The journey always starts at
1047	 * "you are here"; the shape depends on how many stops are chosen on top of it:
1048	 *   • none           → just open the map centred on the user.
1049	 *   • one (chosen OR
1050	 *     destination)   → directions from here to that single show.
1051	 *   • two (chosen +
1052	 *     destination)   → directions here → chosen show → destination, with the
1053	 *                      chosen show passed as a waypoint.
1054	 * Travel mode follows the user's selection. */
1055	function googleMapsUrl() {
1056	  const origin = state.userLatLng; // [lat, lng] — "you are here"
1057	  const fmt = ([lat, lng]) => `${lat},${lng}`;
1058	
1059	  const destShow = state.selectedShowId
1060	    ? state.shows.find((s) => s.id === state.selectedShowId)
1061	    : null;
1062	  let legShow = null;
1063	  if (state.legShowId && (!destShow || state.legShowId !== destShow.id)) {
1064	    legShow = state.shows.find((s) => s.id === state.legShowId) || null;
1065	  }
1066	
1067	  // Ordered geographic stops after the origin: chosen show first, then the
1068	  // destination. The final one is the route's destination; any before it are
1069	  // waypoints.
1070	  const stops = [];
1071	  if (legShow) stops.push([legShow.lat, legShow.lng]);
1072	  if (destShow) stops.push([destShow.lat, destShow.lng]);
1073	
1074	  // Nothing chosen — just open the map centred on the user.
1075	  if (stops.length === 0) {
1076	    return `https://www.google.com/maps/@${fmt(origin)},15z`;
1077	  }
1078	
1079	  const destination = stops[stops.length - 1];
1080	  const waypoints = stops.slice(0, -1);
1081	  let url =
1082	    "https://www.google.com/maps/dir/?api=1" +
1083	    `&origin=${encodeURIComponent(fmt(origin))}` +
1084	    `&destination=${encodeURIComponent(fmt(destination))}` +
1085	    `&travelmode=${googleMapsTravelMode()}`;
1086	  if (waypoints.length) {
1087	    url += `&waypoints=${encodeURIComponent(waypoints.map(fmt).join("|"))}`;
1088	  }
1089	  return url;
1090	}
1091	
1092	/* Point the plan-header Maps link at the current route. The link only exists in
1093	 * the DOM while a plan is rendered (renderJourneyStrip builds it), so there's
1094	 * nothing to show/hide here — just keep its href current. */
1095	function updateMapsRouteLink() {
1096	  const link = document.getElementById("mapsRouteLink");
1097	  if (!link) return;
1098	  link.href = googleMapsUrl();
1099	}
1100	
1101	/* Minutes of slack before the next commitment on the current plan — i.e. the
1102	 * free time you could still fill with a show. Accounts for a chosen leg. Returns
1103	 * null when no commitment is set. */
1104	function planSpareMinutes() {
1105	  const constraint = state.selectedShowId
1106	    ? state.shows.find((s) => s.id === state.selectedShowId)
1107	    : null;
1108	  if (!constraint) return null;
1109	
1110	  const origin = state.userLatLng;
1111	  const destPt = [constraint.lat, constraint.lng];
1112	
1113	  let leg = null;
1114	  if (state.legShowId && state.legShowId !== constraint.id) {
1115	    const cand = state.shows.find((s) => s.id === state.legShowId);
1116	    if (cand && classifyShow(cand, constraint) === "ok") leg = cand;
1117	  }
1118	
1119	  let arriveDest;
1120	  if (leg) {
1121	    const departFromLeg = timeToMinutes(leg.time) + leg.duration;
1122	    arriveDest = departFromLeg + travelMinutes([leg.lat, leg.lng], destPt);
1123	  } else {
1124	    arriveDest = NOW.minutes + travelMinutes(origin, destPt);
1125	  }
1126	  return Math.round(timeToMinutes(constraint.time) - arriveDest);
1127	}
1128	
1129	/* The plan's spare-time prompt, rendered in the plan's middle slot (where a
1130	 * slipped-in show will go): "X min to spare — want to see a show? (N fit below)".
1131	 * The count mirrors the reachable list. Returns "" when there's nothing to
1132	 * offer — no spare time, nothing fits, or the user dismissed it — so the plan
1133	 * falls back to a plain walk connector. */
1134	function spareCtaNode() {
1135	  if (state.spareCtaDismissed) return "";
1136	  const spare = planSpareMinutes();
1137	  if (spare === null || spare <= 0) return "";
1138	  const n = fittingShows().length;
1139	  if (!n) return "";
1140	  const count = `<a class="spare-count spare-jump" href="#shows">${n} ${n === 1 ? "fits" : "fit"} below</a>`;
1141	  return (
1142	    '<div class="plan-spare">' +
1143	    '<button type="button" class="plan-spare-x" aria-label="Dismiss — hide this suggestion" title="Dismiss">&times;</button>' +
1144	    `<p class="spare-line">You have <b>${spare} min</b> to spare — want to see a show? ${count}</p>` +
1145	    "</div>"
1146	  );
1147	}
1148	
1149	/* Wire the in-plan spare prompt: the × dismisses it (revealing a clean plan)
1150	 * and the "N fit below" link jumps down to the selectable show list. */
1151	function wireSpareCta(strip) {
1152	  const x = strip.querySelector(".plan-spare-x");
1153	  if (x) {
1154	    x.addEventListener("click", (e) => {
1155	      e.stopPropagation();
1156	      state.spareCtaDismissed = true;
1157	      renderJourneyStrip();
1158	    });
1159	  }
1160	  const jump = strip.querySelector(".spare-jump");
1161	  if (jump) {
1162	    jump.addEventListener("click", (e) => {
1163	      e.preventDefault();
1164	      const shows = document.getElementById("shows");
1165	      if (shows) shows.scrollIntoView({ behavior: "smooth", block: "start" });
1166	    });
1167	  }
1168	}
1169	
1170	/* One node in the vertical plan: a leading glyph (📍 for "you", the genre emoji
1171	 * for a show), time, title, subtitle, an optional slack chip and an optional
1172	 * extra (e.g. a buy button). */
1173	function planNode(icon, kind, time, title, sub, slackHtmlStr, extraHtml) {
1174	  // Slack chip sits on the time line, to the left of the event time: it reads as
1175	  // the payoff of the travel connector just above ("N min walk" → "made it, X to
1176	  // spare · 15:30–16:30").
1177	  return `
1178	    <div class="plan-node ${kind}">
1179	      <span class="plan-ico" aria-hidden="true">${icon}</span>
1180	      <div class="plan-timerow">${slackHtmlStr || ""}<span class="plan-time">${escapeHtml(time)}</span></div>
1181	      <div class="plan-title">${escapeHtml(title)}</div>
1182	      ${sub ? `<div class="plan-sub">${escapeHtml(sub)}</div>` : ""}
1183	      ${extraHtml || ""}
1184	    </div>`;
1185	}
1186	
1187	/* A travel connector between two plan nodes; verb follows the selected mode. */
1188	function planLeg(mins) {
1189	  return `<div class="plan-leg">${escapeHtml(travelGlyph())} ${formatMins(mins)} ${travelVerb()}</div>`;
1190	}
1191	
1192	/* Booking link for a show on the official Fringe box office. Every show in the
1193	 * data carries a `slug`; the page lives at /tickets/whats-on/<slug>. */
1194	function ticketUrl(show) {
1195	  return show && show.slug
1196	    ? `https://www.edfringe.com/tickets/whats-on/${encodeURIComponent(show.slug)}`
1197	    : "";
1198	}
1199	
1200	/* Buy-ahead link for the chosen stop. Buying ahead skips the on-site box-office
1201	 * queue (~5 min), which matters when a plan is tight. Free shows need no ticket;
1202	 * sold-out shows say so. */
1203	function planBuy(show) {
1204	  if (!show || show.free) return "";
1205	  // `available` (from ticketStatus) is the reliable signal, not the soldOut flag.
1206	  if (show.available === false) return `<span class="plan-soldout">Sold out</span>`;
1207	  const url = ticketUrl(show) || "#";
1208	  return `<a class="plan-buy-inline" href="${escapeHtml(url)}" target="_blank" rel="noopener"
1209	            title="Buy ahead on edfringe.com — skips the box-office queue (~5 min)"
1210	          >&#127915; Buy ahead &middot; skip the queue</a>`;
1211	}
1212	
1213	/* A chip noting the cushion before a show starts (or by how much you'd miss it). */
1214	function planSlack(mins) {
1215	  const m = Math.round(mins);
1216	  return m >= 0
1217	    ? `<span class="plan-slack ok">${m} min to spare</span>`
1218	    : `<span class="plan-slack late">${-m} min late</span>`;
1219	}
1220	
1221	/* Travel duration rounded to whole minutes (never below 1). */
1222	function formatMins(mins) {
1223	  return `${Math.max(1, Math.round(mins))} min`;
1224	}
1225	
1226	/* ---------- Genre filter ---------- */
1227	function buildGenrePanel() {
1228	  const wrap = document.getElementById("genreOptions");
1229	  if (!wrap) return;
1230	  wrap.innerHTML = "";
1231	  GENRES.forEach((genre) => {
1232	    const id = "genre-" + genre.replace(/[^a-z0-9]+/gi, "-").toLowerCase();
1233	    const label = document.createElement("label");
1234	    label.className = "panel-option";
1235	    label.innerHTML = `
1236	      <input type="checkbox" id="${id}" value="${escapeHtml(genre)}"
1237	        ${state.selectedGenres.has(genre) ? "checked" : ""} />
1238	      <span><span class="opt-ico" aria-hidden="true">${genreIcon(genre)}</span> ${escapeHtml(genre)}</span>`;
1239	    const input = label.querySelector("input");
1240	    input.addEventListener("change", () => {
1241	      if (input.checked) state.selectedGenres.add(genre);
1242	      else state.selectedGenres.delete(genre);
1243	      onGenreChange();
1244	    });
1245	    wrap.appendChild(label);
1246	  });
1247	
1248	  // Price: Free / Paid / Both segmented control (idempotent handlers so a
1249	  // Reset-driven rebuild can't double-bind).
1250	  document.querySelectorAll("#priceOptions .seg-btn").forEach((btn) => {
1251	    btn.onclick = () => {
1252	      state.priceFilter = btn.dataset.price;
1253	      updatePriceButtons();
1254	      onGenreChange();
1255	    };
1256	  });
1257	  updatePriceButtons();
1258	
1259	  // Reset every show filter back to "show everything".
1260	  const reset = document.getElementById("filterReset");
1261	  if (reset) {
1262	    reset.onclick = () => {
1263	      state.selectedGenres = new Set(GENRES);
1264	      state.priceFilter = "both";
1265	      buildGenrePanel(); // re-render checkboxes + price state
1266	      onGenreChange();
1267	    };
1268	  }
1269	}
1270	
1271	/* Reflect the active price choice on the Both/Free/Paid segmented control. */
1272	function updatePriceButtons() {
1273	  document.querySelectorAll("#priceOptions .seg-btn").forEach((b) => {
1274	    const on = b.dataset.price === state.priceFilter;
1275	    b.classList.toggle("is-active", on);
1276	    b.setAttribute("aria-pressed", String(on));
1277	  });
1278	}
1279	
1280	function onGenreChange() {
1281	  state.showCap = SHOW_PAGE; // a changed filter resets the list to the first page
1282	  updateGenreValue();
1283	  buildConstraintPanel(); // time/show options depend on the genre + price filter
1284	  refreshMap();           // also re-renders the (mirrored) show list
1285	}
1286	
1287	/* Concise label for the genre filter chip. All (or none) selected reads as
1288	 * "All genres"; a price filter is appended. */
1289	function updateGenreValue() {
1290	  const el = document.querySelector('[data-value="genre"]');
1291	  if (!el) return;
1292	  const n = state.selectedGenres.size;
1293	  let label =
1294	    n === 0 || n === GENRES.length
1295	      ? "All genres"
1296	      : n === 1
1297	      ? [...state.selectedGenres][0]
1298	      : `${n} genres`;
1299	  if (state.priceFilter === "free") label += " · free";
1300	  else if (state.priceFilter === "paid") label += " · paid";
1301	  el.textContent = label;
1302	  // Mirror the single-genre icon onto the chip; a generic mask stands in for
1303	  // "all" or a mix.
1304	  const ico = document.querySelector(".card--genre .fc-ico");
1305	  if (ico) ico.textContent = n === 1 ? genreIcon([...state.selectedGenres][0]) : "🎭";

