1090	// one line per show; the star on the left adds the show to the working
1091	// favourites through the same path an upload takes (applyFavourites), so
1092	// persistence, matching and the live re-plan all follow. The matching/
1093	// filtering itself is pure and lives in ./lib/search.js.
1094	
1095	const SEARCH_LIMIT = 30;
1096	const SEARCH_FILTER_IDS = ["ssfGenre", "ssfSubgenre", "ssfAccess", "ssfAge", "ssfPrice"];
1097	
1098	const searchUi = {
1099	  active: -1, // index of the keyboard-highlighted row, -1 = none
1100	  results: [],
1101	  total: 0,
1102	  debounce: null,
1103	};
1104	
1105	/** Park the search component in the intake stage or under the calendar grid. */
1106	function mountSearch(where) {
1107	  const node = $("showSearch");
1108	  const slot = $(where === "cal" ? "ssSlotCal" : "ssSlotIntake");
1109	  if (!node || !slot || node.parentElement === slot) return;
1110	  // Moving a node drops focus; hand it back so "star one, keep typing" flows on.
1111	  const hadFocus = document.activeElement === $("ssInput");
1112	  slot.appendChild(node);
1113	  if (hadFocus) $("ssInput").focus({ preventScroll: true });
1114	}
1115	
1116	/** Read the five filter selects into a lib/search.js-shaped filters object. */
1117	function currentSearchFilters() {
1118	  const filters = {
1119	    genre: $("ssfGenre").value,
1120	    subgenre: $("ssfSubgenre").value,
1121	    accessibility: $("ssfAccess").value,
1122	  };
1123	  const age = $("ssfAge").value;
1124	  if (age !== "") filters.maxAge = Number(age);
1125	  const price = $("ssfPrice").value;
1126	  if (price === "free") filters.price = "free";
1127	  else if (price !== "") filters.price = Number(price);
1128	  return filters;
1129	}
1130	
1131	/** "AUDIO_DESCRIPTION" → "Audio description". */
1132	function humanizeEnum(v) {
1133	  const s = String(v).replace(/_/g, " ").toLowerCase();
1134	  return s.charAt(0).toUpperCase() + s.slice(1);
1135	}
1136	
1137	/**
1138	 * Fill the data-driven filter options + the placeholder once the catalogue is
1139	 * in. The accessibility select and the price caps disable themselves while the
1140	 * catalogue carries no data behind them — the filters are wired for the fields
1141	 * the scraper will ship (see lib/search.js), but a control that could only
1142	 * match nothing is presented as coming soon, not left to look broken.
1143	 */
1144	function initSearchUI() {
1145	  const input = $("ssInput");
1146	  if (!input || !state.lookups) return;
1147	  input.placeholder =
1148	    `Search all ${state.catalogue.length.toLocaleString("en-GB")} shows — title, performer or venue`;
1149	
1150	  const fill = (sel, values, label) => {
1151	    for (const v of values) {
1152	      const opt = document.createElement("option");
1153	      opt.value = v;
1154	      opt.textContent = label ? label(v) : v;
1155	      sel.appendChild(opt);
1156	    }
1157	  };
1158	  fill($("ssfGenre"), [...(state.lookups.genres || [])].sort());
1159	  fill($("ssfSubgenre"), [...(state.lookups.subgenres || [])].sort());
1160	
1161	  const access = $("ssfAccess");
1162	  if (state.facets.accessibility.length > 0) {
1163	    fill(access, state.facets.accessibility, humanizeEnum);
1164	  } else {
1165	    access.disabled = true;
1166	    access.title = "Accessibility data hasn't landed in our catalogue yet — coming soon";
1167	  }
1168	
1169	  if (!state.facets.hasPrice) {
1170	    const priceSel = $("ssfPrice");
1171	    priceSel.title = "Per-show pricing is coming soon — “Free” already works";
1172	    for (const opt of priceSel.options) {
1173	      if (opt.value !== "" && opt.value !== "free") opt.disabled = true;
1174	    }
1175	  }
1176	}
1177	
1178	function setSearchOpen(open) {
1179	  $("ssPop").hidden = !open;
1180	  $("showSearch").classList.toggle("is-open", open);
1181	  $("ssInput").setAttribute("aria-expanded", String(open));
1182	  if (!open) setActiveRow(-1);
1183	}
1184	
1185	function runSearch() {
1186	  if (!state.index) return; // catalogue still loading — the input just holds the text
1187	  const query = $("ssInput").value;
1188	  const filters = currentSearchFilters();
1189	  if (query.trim() === "" && !hasActiveFilters(filters)) {
1190	    searchUi.results = [];
1191	    searchUi.total = 0;
1192	    setSearchOpen(false);
1193	    return;
1194	  }
1195	  const { results, total } = searchShows(state.catalogue, query, filters, { limit: SEARCH_LIMIT });
1196	  searchUi.results = results;
1197	  searchUi.total = total;
1198	  renderSearchResults();
1199	}
1200	
1201	function renderSearchResults() {
1202	  const list = $("ssResults");
1203	  list.innerHTML = "";
1204	  const favs = new Set(state.favSlugs);
1205	  searchUi.results.forEach((show, i) => {
1206	    list.appendChild(buildSearchRow(show, i, favs.has(show.slug)));
1207	  });
1208	  $("ssEmpty").hidden = searchUi.results.length > 0;
1209	  const foot = $("ssFoot");
1210	  const capped = searchUi.total > searchUi.results.length;
1211	  foot.hidden = !capped;
1212	  if (capped) {
1213	    foot.textContent =
1214	      `Showing ${searchUi.results.length} of ${searchUi.total} matches — keep typing to narrow it down`;
1215	  }
1216	  setActiveRow(-1);
1217	  setSearchOpen(true);
1218	}
1219	
1220	function starLabel(title, isOn) {
1221	  return isOn ? `Remove ${title} from your grid` : `Add ${title} to your grid`;
1222	}
1223	
1224	function buildSearchRow(show, i, isOn) {
1225	  const li = document.createElement("li");
1226	  li.className = "ss-row" + (isOn ? " is-on" : "");
1227	  li.id = `ssOpt${i}`;
1228	  li.setAttribute("role", "option");
1229	  li.setAttribute("aria-selected", "false");
1230	  li.dataset.slug = show.slug;
1231	  li.dataset.title = show.title;
1232	
1233	  const star = document.createElement("button");
1234	  star.type = "button";
1235	  star.className = "ss-star";
1236	  star.textContent = isOn ? "★" : "☆";
1237	  star.setAttribute("aria-label", starLabel(show.title, isOn));
1238	
1239	  const title = document.createElement("span");
1240	  title.className = "ss-row-title";
1241	  title.textContent = show.title;
1242	
1243	  const meta = document.createElement("span");
1244	  meta.className = "ss-row-meta";
1245	  meta.textContent = [
1246	    show.free ? "Free" : null,
1247	    show.genre,
1248	    show.venueName,
1249	    typicalStartTime(show.performances || []),
1250	  ].filter(Boolean).join(" · ");
1251	
1252	  li.append(star, title, meta);
1253	  return li;
1254	}
1255	
1256	/** Re-mark every rendered result row against the current favourites, so the
1257	 *  stars always mirror the grid (called on any favourites change). */
1258	function syncSearchStars() {
1259	  const list = $("ssResults");
1260	  if (!list) return;
1261	  const favs = new Set(state.favSlugs);
1262	  for (const row of list.querySelectorAll(".ss-row")) {
1263	    const on = favs.has(row.dataset.slug);
1264	    row.classList.toggle("is-on", on);
1265	    const star = row.querySelector(".ss-star");
1266	    star.textContent = on ? "★" : "☆";
1267	    star.setAttribute("aria-label", starLabel(row.dataset.title, on));
1268	  }
1269	}
1270	
1271	/** The star toggle: put the show on the grid (through the same path an upload
1272	 *  takes), or lift it back off. */
1273	function toggleShowOnGrid(slug) {
1274	  if (state.favSlugs.includes(slug)) {
1275	    removeFavourite(slug);
1276	    return;
1277	  }
1278	  const slugs = [...state.favSlugs, slug];
1279	  const savedAt = state.savedAt || Date.now();
1280	  saveFavourites(slugs, state.filename, savedAt);
1281	  applyFavourites(slugs, state.filename, savedAt, { scroll: false, keepForced: true, keepWindow: true });
1282	}
1283	
1284	function setActiveRow(i) {
1285	  const rows = [...$("ssResults").querySelectorAll(".ss-row")];
1286	  searchUi.active = i;
1287	  rows.forEach((row, j) => {
1288	    row.classList.toggle("is-active", j === i);
1289	    row.setAttribute("aria-selected", String(j === i));
1290	  });
1291	  const input = $("ssInput");
1292	  if (i >= 0 && rows[i]) {
1293	    input.setAttribute("aria-activedescendant", rows[i].id);
1294	    rows[i].scrollIntoView({ block: "nearest" });
1295	  } else {
1296	    input.removeAttribute("aria-activedescendant");
1297	  }
1298	}
