1303	  for (const id of SEARCH_FILTER_IDS) {
1304	    const sel = $(id);
1305	    const set = sel.value !== "";
1306	    sel.classList.toggle("is-set", set);
1307	    if (set) active++;
1308	  }
1309	  const badge = $("ssBadge");
1310	  badge.hidden = active === 0;
1311	  badge.textContent = String(active);
