1315	function wireShowSearch() {
1316	  const root = $("showSearch");
1317	  const input = $("ssInput");
1318	  if (!root || !input) return;
1319	
1320	  input.addEventListener("input", () => {
1321	    clearTimeout(searchUi.debounce);
1322	    searchUi.debounce = setTimeout(runSearch, 120);
1323	  });
1324	  // Re-focusing a bar that still holds a query (or live filters) reopens it.
1325	  input.addEventListener("focus", () => {
1326	    if (input.value.trim() !== "" || hasActiveFilters(currentSearchFilters())) runSearch();
1327	  });
1328	  input.addEventListener("keydown", (e) => {
1329	    const n = searchUi.results.length;
1330	    if (e.key === "ArrowDown" && n > 0) {
1331	      e.preventDefault();
1332	      if ($("ssPop").hidden) setSearchOpen(true);
1333	      setActiveRow((searchUi.active + 1) % n);
1334	    } else if (e.key === "ArrowUp" && n > 0) {
1335	      e.preventDefault();
