83	/**
84	 * @typedef {object} SearchFilters
85	 * @property {string} [genre]         exact genre label
86	 * @property {string} [subgenre]      exact subgenre label (matched in show.subgenres)
87	 * @property {string} [accessibility] enum value the show must declare
88	 * @property {number} [maxAge]        highest admitted minimum age (inclusive):
89	 *                                    2 excludes nothing rated above 2; unknown excluded
90	 * @property {"free"|number} [price]  "free", or a cap in pounds (inclusive);
91	 *                                    unknown-price shows excluded either way
92	 */
93	
94	/** True when any filter field is set (i.e. filtering would narrow the list). */
95	export function hasActiveFilters(filters) {
96	  const f = filters || {};
97	  return Boolean(f.genre || f.subgenre || f.accessibility) ||
98	    typeof f.maxAge === "number" || f.price === "free" || typeof f.price === "number";
99	}
100	
101	/** The shows passing every set filter (see SearchFilters for the semantics). */
102	export function filterShows(shows, filters) {
103	  const f = filters || {};
104	  return (shows || []).filter((show) => {
105	    if (f.genre && show.genre !== f.genre) return false;
106	    if (f.subgenre && !(show.subgenres || []).includes(f.subgenre)) return false;
107	    if (f.accessibility && !showAccessibility(show).includes(f.accessibility)) return false;
108	    if (typeof f.maxAge === "number") {
109	      const age = ageLimitYears(show);
110	      if (age === null || age > f.maxAge) return false;
111	    }
112	    if (f.price === "free") {
113	      if (showPrice(show) !== 0) return false;
114	    } else if (typeof f.price === "number") {
115	      const price = showPrice(show);
116	      if (price === null || price > f.price) return false;
117	    }
118	    return true;
119	  });
120	}
121	
122	// Case- and accent-insensitive matching: "cafe" finds "Café".
123	function fold(s) {
124	  return String(s || "")
125	    .toLowerCase()
126	    .normalize("NFD")
127	    .replace(/[\u0300-\u036f]/g, "");
128	}
129	
130	// Escape a string for use inside a RegExp (word-boundary probes below).
131	function reEscape(s) {
132	  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
133	}
134	
135	/**
136	 * Rank one show against a folded query. 0 = no match. Title matches outrank
137	 * company/venue matches, and within the title: prefix > word start > anywhere.
138	 * Multi-word queries must land every word somewhere in title+company+venue.
139	 */
140	function scoreShow(show, foldedQuery, tokens) {
141	  const title = fold(show.title);
142	  const rest = fold(`${show.company || ""} ${show.venueName || ""}`);
143	  const hay = `${title} ${rest}`;
144	  for (const t of tokens) {
145	    if (!hay.includes(t)) return 0;
146	  }
147	  if (title.startsWith(foldedQuery)) return 4;
148	  if (new RegExp(`\\b${reEscape(foldedQuery)}`).test(title)) return 3;
149	  if (title.includes(foldedQuery)) return 2;
150	  return 1;
151	}
152	
153	/**
154	 * The main entry: filter, then match the query, then rank.
155	 *
156	 * - Empty query + no active filters → nothing (the UI shows no popup).
157	 * - Empty query + filters → the whole filtered list, A→Z (browse by facet).
158	 * - With a query: ranked matches (see scoreShow), ties A→Z.
159	 *
160	 * @param {object[]} shows        the catalogue (e.g. [...index.values()])
161	 * @param {string} query          raw user text
162	 * @param {SearchFilters} filters
163	 * @param {{limit?: number}} [opts]
164	 * @returns {{results: object[], total: number}} results capped at limit;
165	 *   total is the uncapped match count (for a "showing X of Y" footer)
166	 */
167	export function searchShows(shows, query, filters, { limit = 30 } = {}) {
168	  const foldedQuery = fold(query).trim().replace(/\s+/g, " ");
169	  const tokens = foldedQuery ? foldedQuery.split(" ") : [];
170	  if (tokens.length === 0 && !hasActiveFilters(filters)) return { results: [], total: 0 };
171	
172	  const pool = filterShows(shows, filters);
173	  const byTitle = (a, b) => fold(a.title).localeCompare(fold(b.title));
174	
175	  if (tokens.length === 0) {
176	    const all = [...pool].sort(byTitle);
177	    return { results: all.slice(0, limit), total: all.length };
178	  }
179	
180	  const scored = [];
181	  for (const show of pool) {
182	    const score = scoreShow(show, foldedQuery, tokens);
183	    if (score > 0) scored.push({ show, score });
184	  }
185	  scored.sort((a, b) => b.score - a.score || byTitle(a.show, b.show));
186	  return { results: scored.slice(0, limit).map((s) => s.show), total: scored.length };
187	}
