.filter-chip .card-panel { left: 0; right: auto; min-width: 240px; }
/* The right-most chip's panel opens toward the left so it can't spill off a
   narrow (375px) viewport. */
.card--travel .card-panel { left: auto; right: 0; }

input.new_string:
.filter-chip .card-panel { left: 0; right: auto; min-width: 240px; }
/* The right-most chip's panel opens toward the left so it can't spill off a
   narrow (375px) viewport. */
.card--travel .card-panel { left: auto; right: 0; }
/* The $ chip: a narrow button carrying the mark alone until a price is chosen,
   when it also spells out the current selection. */
.filter-chip--mini .card-trigger { padding: 7px 9px; gap: 4px; }
.fc-money { flex: 0 0 auto; font-weight: 800; font-size: 0.9rem; color: var(--muted); line-height: 1; }
.card--price.is-set .fc-money { color: var(--red); }
.filter-chip .card-value--price[hidden] { display: none; }
/* A tiny dropdown — just the three price choices, so it needn't be panel-wide. */
.card-panel--mini { min-width: 168px; padding: 14px 14px 15px; }
.card-panel--mini .panel-title { margin-bottom: 8px; }

/* --- "Your previous plan" restore bar --- */
/* Sits where the plan would be, offering back a cached plan whose time has
   already passed. Deliberately quiet: an offer, not an alert. */
.restore-bar {
  display: flex; align-items: center; gap: 8px; margin: 12px 0 0;
  padding: 9px 12px; border: 1px dashed var(--line); border-radius: var(--radius);
  background: var(--paper); font-size: 0.82rem; color: var(--muted);
}
.restore-bar[hidden] { display: none; }
.restore-ico { flex: 0 0 auto; font-size: 0.9rem; }
.restore-text { flex: 1 1 auto; min-width: 0; }
.restore-text b { color: var(--ink); font-weight: 700; }
.restore-btn { flex: 0 0 auto; font: inherit; font-weight: 700; font-size: 0.78rem; color: var(--blue); background: transparent; border: 1px solid var(--line); border-radius: 999px; padding: 5px 12px; cursor: pointer; }
.restore-btn:hover { border-color: var(--blue); background: #fff; }
.restore-x { flex: 0 0 auto; border: none; background: transparent; color: var(--muted); font-size: 1.1rem; line-height: 1; cursor: pointer; width: 24px; height: 24px; border-radius: 8px; }
.restore-x:hover { color: var(--ink); background: rgba(0, 0, 0, 0.05); }
.restore-btn:focus-visible, .restore-x:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }

