    n === 0 || n === GENRES.length
      ? "All genres"
      : n === 1
      ? [...state.selectedGenres][0]
      : `${n} genres`;
  if (state.priceFilter === "free") label += " · free";
  else if (state.priceFilter === "paid") label += " · paid";
  el.textContent = label;
