+function readStore(key) {
+  try {
+    const raw = localStorage.getItem(key);
+    return raw ? JSON.parse(raw) : null;
+  } catch (err) {
+    console.info("EdFringeNow: couldn't read saved settings", err);
+    return null;
+  }
