// One driver, re-pointed per shot: node shot.mjs <url> <out.png> [clickSelector...]
import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';

const [url, out, ...clicks] = process.argv.slice(2);
const width = Number(process.env.W || 900);
const height = Number(process.env.H || 1100);

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width, height } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));

await page.goto(url, { waitUntil: 'networkidle' });
await page.waitForTimeout(600);
for (const sel of clicks) {
  if (sel.startsWith('wait:')) { await page.waitForTimeout(Number(sel.slice(5))); continue; }
  if (sel.startsWith('eval:')) { await page.evaluate(sel.slice(5)); continue; }
  await page.click(sel);
  await page.waitForTimeout(350);
}
await page.screenshot({ path: out, fullPage: !process.env.CLIP });
const real = errors.filter((e) => !/favicon|ERR_CONNECTION_RESET|tile\.openstreetmap/.test(e));
if (real.length) console.log('CONSOLE ERRORS:\n' + real.join('\n'));
else console.log('no console errors');
await browser.close();

