input.new_string:
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width, height } });
// External hosts are unreachable from headless Chromium here (the agent proxy
// can't be tunnelled), so Leaflet + fonts are faked: block the requests and
// stand a chainable no-op `L` in the CDN script's place. Everything except the
// map itself then renders for real.
await page.route('**://unpkg.com/**', (r) => r.abort());
await page.route('**://fonts.googleapis.com/**', (r) => r.abort());
await page.route('**://fonts.gstatic.com/**', (r) => r.abort());
await page.route('**://*.tile.openstreetmap.org/**', (r) => r.abort());
await page.addInitScript(() => {
  const noop = new Proxy(function () {}, {
    get: (t, k) => (k === 'then' ? undefined : noop),
    apply: () => noop,
    construct: () => noop,
  });
  window.L = noop;
});

