+  const where = stale.destLabel || (legShow && legShow.title) || "";
+  const when = stale.selectedTime || (legShow && legShow.time) || "";
+  text.innerHTML =
+    where && when
+      ? `Last time you were heading to <b>${escapeHtml(where)}</b> by ${escapeHtml(when)} — that has passed.`
