// Drives the Now page's localStorage cache: set a plan, reload, check it came
// back; then age it out and check the restore bar offers it.
import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 430, height: 900 } });
for (const p of ['**://unpkg.com/**', '**://fonts.googleapis.com/**', '**://fonts.gstatic.com/**', '**://*.tile.openstreetmap.org/**'])
  await page.route(p, (r) => r.abort());
await page.addInitScript(() => {
  const noop = new Proxy(function () {}, { get: (t, k) => (k === 'then' ? undefined : noop), apply: () => noop, construct: () => noop });
  window.L = noop;
});
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));

const KEY = 'edfringenow.now.v1';
const STALE = 'edfringenow.now.stale.v1';
const url = 'http://localhost:8000/';

await page.goto(url, { waitUntil: 'networkidle' });
await page.waitForTimeout(500);

// 1. Change some filters + commit a show, then read what got cached.
await page.click('.card--subgenre .card-trigger');
await page.click('#subgenreOptions .panel-option:nth-child(2) input');
await page.keyboard.press('Escape');
await page.click('.cta-trigger');
await page.waitForTimeout(300);
await page.click('#showPickList .show-pick');
await page.waitForTimeout(300);
const saved = await page.evaluate((k) => JSON.parse(localStorage.getItem(k)), KEY);
console.log('1. cached after committing:', JSON.stringify(saved));

// 2. Reload — the filters and the (still future) plan should come straight back.
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(600);
console.log('2. after reload — chips:', await page.textContent('[data-value="subgenre"]'),
  '| plan head:', (await page.textContent('#journeyStrip')).trim().slice(0, 60).replace(/\s+/g, ' '),
  '| restore bar hidden:', await page.getAttribute('#restoreBar', 'hidden') !== null);

// 3. Age the cached plan into the past, reload: plan dropped, restore offered.
await page.evaluate(([k, s]) => {
  const v = JSON.parse(localStorage.getItem(k));
  v.selectedTime = '09:00';
  localStorage.setItem(k, JSON.stringify(v));
  localStorage.removeItem(s);
}, [KEY, STALE]);
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(600);
console.log('3. stale reload — plan empty:', (await page.textContent('#journeyStrip')).trim() === '',
  '| restore bar:', (await page.textContent('#restoreText')).trim());
await page.screenshot({ path: 'restore-bar.png' });

// 4. Restore puts it back.
await page.click('#restoreBtn');
await page.waitForTimeout(400);
console.log('4. after Restore — plan:', (await page.textContent('#journeyStrip')).trim().slice(0, 70).replace(/\s+/g, ' '),
  '| bar hidden:', await page.getAttribute('#restoreBar', 'hidden') !== null);

console.log(errors.length ? 'ERRORS:\n' + errors.join('\n') : 'no page errors');
await browser.close();

