+  const meta = document.createElement("span");
+  meta.className = "ss-row-meta";
+  meta.textContent = [
+    show.free ? "Free" : null,
+    show.genre,
+    show.venueName,
+    typicalStartTime(show.performances || []),
+  ].filter(Boolean).join(" · ");
