const facetById = (key) => SEARCH_FACETS.find((f) => f.key === key);

/** Is this facet narrowing the search right now? */
function facetIsSet(facet) {
  const v = searchUi.filters[facet.key];
  return facet.multi ? v.size > 0 : v !== "";
