+  if (facet.valuesOf) {
+    for (const show of pool) {
+      for (const v of facet.valuesOf(show)) {
+        if (counts.has(v)) counts.set(v, counts.get(v) + 1);
+      }
+    }
+  } else {
+    for (const show of pool) {
+      for (const v of values) if (facet.matches(show, v)) counts.set(v, counts.get(v) + 1);
+    }
+  }
+  return counts;
